def transform(grid):
    n=len(grid)
    # The colored diagonals define values by diagonal offset. Repeat the
    # observed offset pattern across the board, retaining the input where
    # the encoding does not specify an offset.
    vals={}
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v:
                vals[c-r]=v
    return [[vals.get((c-r), 0) for c in range(n)] for r in range(n)]
